SELECT CASE WHEN EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relname = 'backup_logs' AND c.relrowsecurity = true) AND EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = 'backup_logs' AND policyname = 'backup_logs_tenant_all') THEN 'ok' ELSE 'FALHOU: backup_logs sem RLS ou sem policy tenant' END;
